create or replace function public.sales_commercial_summary_capture_v610(p_tenant_id uuid,p_location_id uuid,p_device_id uuid,p_sale_id uuid,p_source_type text,p_source_id uuid,p_order_type text,p_summary jsonb) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_discount_type text:=lower(trim(coalesce(p_summary->>'discount_type','none')));v_discount_value numeric:=greatest(coalesce(nullif(p_summary->>'discount_value','')::numeric,0),0);v_doc_discount numeric:=greatest(coalesce(nullif(p_summary->>'document_discount_total','')::numeric,0),0);v_charge_total numeric:=greatest(coalesce(nullif(p_summary->>'classified_charge_total','')::numeric,0),0);v_breakdown jsonb:=coalesce(p_summary->'charge_breakdown','[]'::jsonb);v_grand numeric; begin if not private.erp_user_has_tenant_access(p_tenant_id) then raise exception 'Access denied';end if;perform private.erp_validate_transaction_origin(p_tenant_id,p_location_id,p_device_id,'sales');select grand_total into v_grand from public.sales where id=p_sale_id and tenant_id=p_tenant_id and status='posted';if not found then raise exception 'Posted sale not found';end if;if v_discount_type not in('none','fixed','percent') then raise exception 'Invalid discount type';end if;if jsonb_typeof(v_breakdown)<>'array' then raise exception 'Charge breakdown must be an array';end if;insert into public.sale_commercial_summary_v610(tenant_id,sale_id,source_type,source_id,order_type,discount_type,discount_value,document_discount_total,classified_charge_total,charge_breakdown) values(p_tenant_id,p_sale_id,lower(trim(coalesce(p_source_type,'sale'))),p_source_id,lower(trim(coalesce(p_order_type,'sale'))),v_discount_type,v_discount_value,v_doc_discount,v_charge_total,v_breakdown) on conflict(tenant_id,sale_id) do update set source_type=excluded.source_type,source_id=excluded.source_id,order_type=excluded.order_type,discount_type=excluded.discount_type,discount_value=excluded.discount_value,document_discount_total=excluded.document_discount_total,classified_charge_total=excluded.classified_charge_total,charge_breakdown=excluded.charge_breakdown;return jsonb_build_object('success',true,'sale_id',p_sale_id,'grand_total',v_grand,'document_discount_total',v_doc_discount,'classified_charge_total',v_charge_total);end;$$;;
